/* Container & Base Setup */
* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

body, .preview-box {
  width: 100%;
  height: 100vh;
  overflow: hidden;
  background-color: #060813;
  display: flex;
  justify-content: center;
  align-items: center;
  position: relative;
  font-family: 'Segoe UI', system-ui, sans-serif;
}

/* Canvas Layer */
#quantum-canvas {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  z-index: 1;
  pointer-events: none;
}

/* Central Neon Core */
.quantum-core {
  position: relative;
  z-index: 2;
  width: 130px;
  height: 130px;
  border-radius: 50%;
  background: radial-gradient(circle, rgba(0, 242, 254, 0.4) 0%, rgba(147, 51, 234, 0.15) 60%, transparent 100%);
  box-shadow: 0 0 50px rgba(0, 242, 254, 0.6), inset 0 0 30px rgba(147, 51, 234, 0.7);
  border: 1.5px solid rgba(0, 242, 254, 0.5);
  display: flex;
  align-items: center;
  justify-content: center;
  backdrop-filter: blur(10px);
  animation: corePulse 3s ease-in-out infinite alternate;
}

/* Outer Orbit Rings */
.orbital-ring {
  position: absolute;
  width: 210px;
  height: 210px;
  border-radius: 50%;
  border: 1.5px dashed rgba(0, 242, 254, 0.4);
  animation: rotateClockwise 10s linear infinite;
  box-shadow: 0 0 20px rgba(0, 242, 254, 0.2);
}

.orbital-ring-outer {
  position: absolute;
  width: 280px;
  height: 280px;
  border-radius: 50%;
  border: 1px dotted rgba(236, 72, 153, 0.5);
  animation: rotateCounter 15s linear infinite;
}

/* Keyframe Animations */
@keyframes corePulse {
  0% {
    transform: scale(0.94);
    box-shadow: 0 0 35px rgba(0, 242, 254, 0.4);
  }
  100% {
    transform: scale(1.06);
    box-shadow: 0 0 75px rgba(147, 51, 234, 0.85), 0 0 110px rgba(0, 242, 254, 0.6);
  }
}

@keyframes rotateClockwise {
  from { transform: rotate(0deg); }
  to { transform: rotate(360deg); }
}

@keyframes rotateCounter {
  from { transform: rotate(360deg) rotateX(55deg); }
  to { transform: rotate(0deg) rotateX(55deg); }
}

